package com.vitalregentimers;

import java.awt.Color;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * InfoBox showing a hitpoints or prayer regeneration countdown.
 * Text, color, visibility and tooltip are supplied by the plugin so the same class
 * can be used for both timers.
 *
 * Based on the Special Attack Timers plugin by AnuVen (https://github.com/AnuVen/special-attack-timers).
 */
public class VitalRegenInfoBox extends InfoBox
{
	private final Supplier<String> text;
	private final Supplier<Color> color;
	private final BooleanSupplier visible;
	private final Supplier<String> tooltip;

	public VitalRegenInfoBox(Plugin plugin, Supplier<String> text, Supplier<Color> color,
		BooleanSupplier visible, Supplier<String> tooltip)
	{
		super(null, plugin);
		this.text = text;
		this.color = color;
		this.visible = visible;
		this.tooltip = tooltip;
	}

	@Override
	public String getText()
	{
		return text.get();
	}

	@Override
	public Color getTextColor()
	{
		return color.get();
	}

	@Override
	public boolean render()
	{
		return visible.getAsBoolean();
	}

	@Override
	public String getTooltip()
	{
		return tooltip.get();
	}
}

package com.vitalregentimers;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Transparent (number-only) version of the hitpoints/prayer regen infobox,
 * used when "Transparent Infobox" is enabled. Movable with Alt-drag, so it can be
 * placed directly on top of the hitpoints or prayer orb.
 *
 * Subclassed once per timer so each overlay keeps its own saved position.
 *
 * Based on the Special Attack Timers plugin by AnuVen (https://github.com/AnuVen/special-attack-timers).
 */
public abstract class VitalRegenTextOverlay extends Overlay
{
	private final Client client;
	private final VitalRegenTimersConfig config;
	private final RuneLiteConfig runeLiteConfig;

	protected VitalRegenTextOverlay(Client client, VitalRegenTimersPlugin plugin,
		VitalRegenTimersConfig config, RuneLiteConfig runeLiteConfig)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.runeLiteConfig = runeLiteConfig;

		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
		// Not snappable so it can be dropped directly onto the minimap orbs
		setSnappable(false);
	}

	/**
	 * @return whether this timer is enabled in the config
	 */
	protected abstract boolean isEnabled();

	/**
	 * @return whether the timer currently has something to show
	 */
	protected abstract boolean isVisible();

	protected abstract String getTimerText();

	protected abstract Color getTimerColor();

	protected abstract VitalRegenTimersConfig.DisplayFormat getDisplayFormat();

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		if (!isEnabled() || !config.transparentInfoBox() || !isVisible())
		{
			return null;
		}

		String text = getTimerText();
		Font font = config.useCustomFont()
			? config.timerFont().getFont()
			: runeLiteConfig.infoboxFont().getFont().deriveFont((float) config.transparentFontSize());
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();

		// Fixed width so the number doesn't shift while counting down
		int boxWidth = getMaxTextWidth(metrics);
		int x = (boxWidth - metrics.stringWidth(text)) / 2;
		int y = metrics.getAscent();

		drawText(graphics, text, x, y, getTimerColor());

		return new Dimension(boxWidth + 1, metrics.getHeight() + 1);
	}

	private void drawText(Graphics2D graphics, String text, int x, int y, Color color)
	{
		VitalRegenTimersConfig.TextStyle style = config.textStyle();
		if (style == VitalRegenTimersConfig.TextStyle.RUNELITE)
		{
			style = runeLiteConfig.infoBoxTextOutline()
				? VitalRegenTimersConfig.TextStyle.OUTLINE
				: VitalRegenTimersConfig.TextStyle.SHADOW;
		}

		graphics.setColor(Color.BLACK);
		switch (style)
		{
			case OUTLINE:
				graphics.drawString(text, x - 1, y);
				graphics.drawString(text, x + 1, y);
				graphics.drawString(text, x, y - 1);
				graphics.drawString(text, x, y + 1);
				break;
			case SHADOW:
				graphics.drawString(text, x + 1, y + 1);
				break;
			case NONE:
			default:
				break;
		}

		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	/**
	 * Width of the widest text the timer can show: three digits for ticks (up to 100),
	 * two for seconds (up to 60), or "00.0s" for decimals.
	 */
	private int getMaxTextWidth(FontMetrics metrics)
	{
		int maxDigitWidth = 0;
		for (char digit = '0'; digit <= '9'; digit++)
		{
			maxDigitWidth = Math.max(maxDigitWidth, metrics.charWidth(digit));
		}

		switch (getDisplayFormat())
		{
			case DECIMALS:
				return 3 * maxDigitWidth + metrics.charWidth('.') + metrics.charWidth('s');
			case SECONDS:
				return 2 * maxDigitWidth;
			case TICKS:
			default:
				return 3 * maxDigitWidth;
		}
	}
}

package com.vitalregentimers;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.FontType;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * Based on the Special Attack Timers plugin by AnuVen (https://github.com/AnuVen/special-attack-timers).
 */
@ConfigGroup(VitalRegenTimersConfig.GROUP)
public interface VitalRegenTimersConfig extends Config
{
	String GROUP = "vitalregentimers";

	@Getter
	@RequiredArgsConstructor
	enum DisplayFormat
	{
		TICKS("Ticks"),
		SECONDS("Seconds"),
		DECIMALS("Decimals");

		private final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}

	@Getter
	@RequiredArgsConstructor
	enum TextStyle
	{
		RUNELITE("Same as RuneLite"),
		OUTLINE("Outline"),
		SHADOW("Shadow"),
		NONE("None");

		private final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigSection(
		name = "Display",
		description = "How the timers are displayed",
		position = 0
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "transparentInfoBox",
		name = "Transparent Infobox",
		description = "Show only the timer number, with no icon or background. Alt-drag it onto the orbs.",
		position = 1,
		section = displaySection
	)
	default boolean transparentInfoBox()
	{
		return false;
	}

	@Range(min = 8, max = 48)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "transparentFontSize",
		name = "Transparent Font Size",
		description = "Font size of the Transparent Infobox timers (when Custom Font is off).",
		position = 2,
		section = displaySection
	)
	default int transparentFontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "useCustomFont",
		name = "Custom Font",
		description = "Use the font below for the Transparent Infobox timers instead of RuneLite's infobox font",
		position = 3,
		section = displaySection
	)
	default boolean useCustomFont()
	{
		return false;
	}

	@ConfigItem(
		keyName = "timerFont",
		name = "Font",
		description = "Font, size, bold and italic for the Transparent Infobox timers (when Custom Font is on)",
		position = 4,
		section = displaySection
	)
	default FontType timerFont()
	{
		return FontType.REGULAR;
	}

	@ConfigItem(
		keyName = "textStyle",
		name = "Text Outline",
		description = "Outline, shadow or nothing around the Transparent Infobox timer text",
		position = 5,
		section = displaySection
	)
	default TextStyle textStyle()
	{
		return TextStyle.RUNELITE;
	}

	@ConfigSection(
		name = "Hitpoints Regen Timer",
		description = "Countdown until your next hitpoint regenerates (or decays when overhealed)",
		position = 10
	)
	String hpRegenSection = "hpRegen";

	@ConfigItem(
		keyName = "showHpRegenTimer",
		name = "Show HP Regen Timer",
		description = "Show a countdown until your next hitpoint regenerates (halved with Rapid Heal)",
		position = 11,
		section = hpRegenSection
	)
	default boolean showHpRegenTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hpOnlyWithRapidHeal",
		name = "Only With Rapid Heal",
		description = "Only show the hitpoints timer while Rapid Heal is active",
		position = 12,
		section = hpRegenSection
	)
	default boolean hpOnlyWithRapidHeal()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hpDisplayFormat",
		name = "HP Display Format",
		description = "Ticks (game ticks), Seconds (whole), or Decimals (e.g. 29.4s)",
		position = 13,
		section = hpRegenSection
	)
	default DisplayFormat hpDisplayFormat()
	{
		return DisplayFormat.TICKS;
	}

	@ConfigItem(
		keyName = "hpShowWhenFull",
		name = "Show When HP Is Full",
		description = "Keep showing the hitpoints timer when your hitpoints are full (useful for Rapid Heal flicking)",
		position = 14,
		section = hpRegenSection
	)
	default boolean hpShowWhenFull()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hpShowOverhealDecay",
		name = "Show Overheal Decay",
		description = "When overhealed, show the countdown until your boosted hitpoints decay by 1",
		position = 15,
		section = hpRegenSection
	)
	default boolean hpShowOverhealDecay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "hpRegenColor",
		name = "HP Regen Color",
		description = "Color of the hitpoints regen timer",
		position = 16,
		section = hpRegenSection
	)
	default Color hpRegenColor()
	{
		return new Color(255, 255, 255, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "hpDecayColor",
		name = "HP Overheal Decay Color",
		description = "Color of the hitpoints timer while overhealed (counting down to decay)",
		position = 17,
		section = hpRegenSection
	)
	default Color hpDecayColor()
	{
		return new Color(255, 165, 0, 255);
	}

	@ConfigSection(
		name = "Prayer Regen Timer",
		description = "Countdown until your next prayer point from a Prayer regeneration potion",
		position = 20
	)
	String prayerRegenSection = "prayerRegen";

	@ConfigItem(
		keyName = "showPrayerRegenTimer",
		name = "Show Prayer Regen Timer",
		description = "While a Prayer regeneration potion or Prayer enhance (Chambers of Xeric) is active, show a countdown "
			+ "until the next prayer point (prayer does not regenerate on its own)",
		position = 21,
		section = prayerRegenSection
	)
	default boolean showPrayerRegenTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "prayerDisplayFormat",
		name = "Prayer Display Format",
		description = "Ticks (game ticks), Seconds (whole), or Decimals (e.g. 29.4s)",
		position = 22,
		section = prayerRegenSection
	)
	default DisplayFormat prayerDisplayFormat()
	{
		return DisplayFormat.TICKS;
	}

	@Alpha
	@ConfigItem(
		keyName = "prayerRegenColor",
		name = "Prayer Regen Color",
		description = "Color of the prayer regen timer",
		position = 23,
		section = prayerRegenSection
	)
	default Color prayerRegenColor()
	{
		return new Color(255, 255, 255, 255);
	}
}

package com.vitalregentimers;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.ItemID;
import net.runelite.api.SpriteID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@PluginDescriptor(
	name = "HP & Prayer Regen Timers",
	description = "Tick countdowns for hitpoints regeneration (with Rapid Heal and overheal decay) and Prayer regeneration potions",
	tags = {"hitpoints", "hp", "prayer", "regen", "regeneration", "timer", "ticks", "rapid", "heal", "overheal", "potion"}
)
public class VitalRegenTimersPlugin extends Plugin
{
	@Inject
	private VitalRegenTimersConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private VitalRegenTracker vitalRegenTracker;

	@Inject
	private HitpointsRegenTextOverlay hpRegenTextOverlay;

	@Inject
	private PrayerRegenTextOverlay prayerRegenTextOverlay;

	/**
	 * Hitpoints regen timer infobox, created when showHpRegenTimer is enabled (non-transparent mode).
	 */
	private VitalRegenInfoBox hpRegenInfoBox;

	/**
	 * Prayer regen timer infobox, created when showPrayerRegenTimer is enabled (non-transparent mode).
	 */
	private VitalRegenInfoBox prayerRegenInfoBox;

	@Provides
	VitalRegenTimersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(VitalRegenTimersConfig.class);
	}

	@Override
	protected void startUp()
	{
		vitalRegenTracker.reset();
		eventBus.register(vitalRegenTracker);
		overlayManager.add(hpRegenTextOverlay);
		overlayManager.add(prayerRegenTextOverlay);
		updateInfoBoxes();
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(vitalRegenTracker);
		overlayManager.remove(hpRegenTextOverlay);
		overlayManager.remove(prayerRegenTextOverlay);
		removeInfoBoxes();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!VitalRegenTimersConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "transparentInfoBox":
			case "showHpRegenTimer":
			case "showPrayerRegenTimer":
				updateInfoBoxes();
				break;
			default:
				break;
		}
	}

	/**
	 * Adds or removes the hitpoints and prayer regen infoboxes based on config.
	 * In transparent mode, the text overlays are shown instead.
	 */
	private void updateInfoBoxes()
	{
		boolean transparent = config.transparentInfoBox();

		if (config.showHpRegenTimer() && !transparent)
		{
			if (hpRegenInfoBox == null)
			{
				hpRegenInfoBox = new VitalRegenInfoBox(this,
					this::getHpRegenTimerText,
					this::getHpRegenTimerColor,
					this::isHpRegenTimerVisible,
					() -> vitalRegenTracker.isOverhealed() ? "Hitpoints Decay Timer" : "Hitpoints Regen Timer");
				spriteManager.getSpriteAsync(SpriteID.MINIMAP_ORB_HITPOINTS_ICON, 0, img ->
				{
					if (img != null && hpRegenInfoBox != null)
					{
						hpRegenInfoBox.setImage(img);
						infoBoxManager.addInfoBox(hpRegenInfoBox);
					}
				});
			}
		}
		else if (hpRegenInfoBox != null)
		{
			infoBoxManager.removeInfoBox(hpRegenInfoBox);
			hpRegenInfoBox = null;
		}

		if (config.showPrayerRegenTimer() && !transparent)
		{
			if (prayerRegenInfoBox == null)
			{
				prayerRegenInfoBox = new VitalRegenInfoBox(this,
					this::getPrayerRegenTimerText,
					config::prayerRegenColor,
					this::isPrayerRegenTimerVisible,
					() -> "Prayer Regen Timer");
				prayerRegenInfoBox.setImage(itemManager.getImage(ItemID.PRAYER_REGENERATION_POTION4));
				infoBoxManager.addInfoBox(prayerRegenInfoBox);
			}
		}
		else if (prayerRegenInfoBox != null)
		{
			infoBoxManager.removeInfoBox(prayerRegenInfoBox);
			prayerRegenInfoBox = null;
		}
	}

	private void removeInfoBoxes()
	{
		if (hpRegenInfoBox != null)
		{
			infoBoxManager.removeInfoBox(hpRegenInfoBox);
			hpRegenInfoBox = null;
		}
		if (prayerRegenInfoBox != null)
		{
			infoBoxManager.removeInfoBox(prayerRegenInfoBox);
			prayerRegenInfoBox = null;
		}
	}

	/**
	 * @return whether the hitpoints regen timer has something to show right now
	 */
	public boolean isHpRegenTimerVisible()
	{
		if (!config.showHpRegenTimer())
		{
			return false;
		}
		if (config.hpOnlyWithRapidHeal() && !vitalRegenTracker.isRapidHealActive())
		{
			return false;
		}
		if (vitalRegenTracker.isOverhealed())
		{
			return config.hpShowOverhealDecay();
		}
		return !vitalRegenTracker.isHpFull() || config.hpShowWhenFull();
	}

	public String getHpRegenTimerText()
	{
		return VitalRegenTracker.format(vitalRegenTracker.getHpTicksRemaining(), config.hpDisplayFormat());
	}

	public Color getHpRegenTimerColor()
	{
		return vitalRegenTracker.isOverhealed() ? config.hpDecayColor() : config.hpRegenColor();
	}

	/**
	 * @return whether the prayer regen timer has something to show right now
	 */
	public boolean isPrayerRegenTimerVisible()
	{
		return config.showPrayerRegenTimer() && vitalRegenTracker.isPrayerRegenActive();
	}

	public String getPrayerRegenTimerText()
	{
		return VitalRegenTracker.format(vitalRegenTracker.getPrayerTicksRemaining(), config.prayerDisplayFormat());
	}
}

package com.vitalregentimers;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks the hitpoints regeneration timer and the Prayer regeneration potion timer,
 * so they can be shown as a tick countdown.
 *
 * Hitpoints:
 * - Regenerates (or, when overhealed, decays) 1 HP every 100 ticks (60 seconds).
 * - Rapid Heal halves the regen interval to 50 ticks.
 * - Toggling Rapid Heal resets the timer.
 * This mirrors the timing used by RuneLite's built-in Regeneration Meter plugin.
 *
 * Prayer:
 * - Prayer does not regenerate on its own. While a Prayer regeneration potion is active,
 *   1 prayer point is restored every 12 ticks (7.2 seconds).
 * - The timer resyncs every time the game updates the potion varbit (once per restored point),
 *   the same approach used by the Prayer Regeneration Helper plugin.
 * - Chambers of Xeric Prayer enhance restores 1 point every floor(500 / (floor(prayer level / 2) + 31))
 *   ticks. Its varbit holds the remaining cycles, so the time left is cycles * rate and the time to
 *   the next point is that modulo the rate. Timing taken from the Cox Additions plugin
 *   (https://github.com/MoreBuchus/buchus-plugins, BSD 2-Clause License).
 */
@Singleton
public class VitalRegenTracker
{
	/**
	 * Hitpoints regenerate 1 HP every 100 game ticks (60 seconds).
	 */
	public static final int HP_REGEN_TICKS = 100;

	/**
	 * Rapid Heal halves the hitpoints regeneration interval.
	 */
	public static final int RAPID_HEAL_REGEN_TICKS = HP_REGEN_TICKS / 2;

	/**
	 * A Prayer regeneration potion restores 1 prayer point every 12 game ticks.
	 */
	public static final int PRAYER_REGEN_POTION_TICKS = 12;

	private final Client client;

	/**
	 * Ticks left on the Chambers of Xeric Prayer enhance potion, counting down each game tick.
	 * -1 when no Prayer enhance is active.
	 */
	private int prayerEnhanceTicks = -1;

	/**
	 * Game ticks since the last hitpoints regen/decay. Counts up to the current cycle length, then wraps.
	 * Starts at -2 after logging in or hopping, matching RuneLite's Regeneration Meter.
	 */
	private int ticksSinceHpRegen = 0;

	/**
	 * Current hitpoints regen cycle length in ticks (100, or 50 with Rapid Heal).
	 */
	@Getter
	private int hpRegenCycleTicks = HP_REGEN_TICKS;

	/**
	 * Value used when no Prayer regeneration potion is active.
	 */
	private static final int NO_PRAYER_REGEN = -1;

	/**
	 * Ticks until the next prayer point from a Prayer regeneration potion.
	 * Set to 12 whenever the potion varbit updates, then counts down each game tick.
	 */
	private int prayerTicksUntilRegen = NO_PRAYER_REGEN;

	@Inject
	public VitalRegenTracker(Client client)
	{
		this.client = client;
	}

	/**
	 * Resets all tracking state.
	 */
	public void reset()
	{
		ticksSinceHpRegen = 0;
		hpRegenCycleTicks = HP_REGEN_TICKS;
		prayerTicksUntilRegen = NO_PRAYER_REGEN;
		prayerEnhanceTicks = -1;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Same offset RuneLite's Regeneration Meter uses after logging in/hopping
			ticksSinceHpRegen = -2;
			prayerTicksUntilRegen = NO_PRAYER_REGEN;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.PRAYER_RAPIDHEAL)
		{
			// Toggling Rapid Heal resets the hitpoints timer
			ticksSinceHpRegen = 0;
		}
		else if (event.getVarbitId() == VarbitID.PRAYER_REGENERATION_POTION_TIMER)
		{
			// The game updates this varbit every time the potion restores a prayer point,
			// so every change > 0 marks the start of a new 12 tick cycle.
			// Same approach as the "Prayer Regeneration Helper" plugin.
			if (event.getValue() > 0)
			{
				prayerTicksUntilRegen = PRAYER_REGEN_POTION_TICKS;
			}
			else
			{
				prayerTicksUntilRegen = NO_PRAYER_REGEN;
			}
		}
		else if (event.getVarbitId() == VarbitID.RAIDS_PRAYERENHANCE_TIMER)
		{
			// The varbit holds the remaining Prayer enhance cycles and changes every time a point is
			// restored, so the countdown resyncs on every change (same as the Cox Additions plugin).
			prayerEnhanceTicks = event.getValue() > 0 ? event.getValue() * getPrayerEnhanceRate() : -1;
		}
	}

	/**
	 * @return ticks between Prayer enhance restores for the current prayer level
	 */
	private int getPrayerEnhanceRate()
	{
		return 500 / (client.getRealSkillLevel(Skill.PRAYER) / 2 + 31);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		hpRegenCycleTicks = client.isPrayerActive(Prayer.RAPID_HEAL) ? RAPID_HEAL_REGEN_TICKS : HP_REGEN_TICKS;
		ticksSinceHpRegen = (ticksSinceHpRegen + 1) % hpRegenCycleTicks;

		if (prayerTicksUntilRegen >= 0)
		{
			prayerTicksUntilRegen--;
		}

		if (prayerEnhanceTicks >= 0)
		{
			prayerEnhanceTicks--;
		}
	}

	/**
	 * @return game ticks until the next hitpoint regenerates (or decays when overhealed)
	 */
	public int getHpTicksRemaining()
	{
		return remaining(ticksSinceHpRegen, hpRegenCycleTicks);
	}

	/**
	 * @return game ticks until the next prayer point is restored by a Prayer regeneration potion
	 */
	public int getPrayerTicksRemaining()
	{
		if (prayerTicksUntilRegen < 0 && isPrayerEnhanceActive())
		{
			// Counts rate -> 1, like the Cox Additions "Regen Cycle" timer
			return prayerEnhanceTicks % getPrayerEnhanceRate() + 1;
		}
		// Counts 12 -> 1 (like Prayer Regeneration Helper) instead of 11 -> 0
		return prayerTicksUntilRegen + 1;
	}

	/**
	 * @return true while the Rapid Heal prayer is active
	 */
	public boolean isRapidHealActive()
	{
		return client.isPrayerActive(Prayer.RAPID_HEAL);
	}

	/**
	 * @return true while a Prayer regeneration potion is active
	 */
	public boolean isPrayerRegenActive()
	{
		return prayerTicksUntilRegen >= 0 || isPrayerEnhanceActive();
	}

	/**
	 * @return true while a Chambers of Xeric Prayer enhance potion is active
	 */
	public boolean isPrayerEnhanceActive()
	{
		return prayerEnhanceTicks >= 0;
	}

	/**
	 * @return true if current hitpoints are above the real hitpoints level (overheal decays instead of regenerating)
	 */
	public boolean isOverhealed()
	{
		return client.getBoostedSkillLevel(Skill.HITPOINTS) > client.getRealSkillLevel(Skill.HITPOINTS);
	}

	/**
	 * @return true if hitpoints are exactly at the real level, meaning the timer has no visible effect
	 */
	public boolean isHpFull()
	{
		return client.getBoostedSkillLevel(Skill.HITPOINTS) == client.getRealSkillLevel(Skill.HITPOINTS);
	}

	/**
	 * Converts "ticks since last regen" into "ticks until next regen".
	 * Shows 0 on the regen tick itself instead of the full cycle length,
	 * like a regular countdown timer.
	 */
	private static int remaining(int ticksSince, int cycle)
	{
		int ticks = cycle - Math.floorMod(ticksSince, cycle);
		return ticks == cycle ? 0 : ticks;
	}

	/**
	 * Formats a tick count using the configured display format.
	 */
	public static String format(int ticks, VitalRegenTimersConfig.DisplayFormat format)
	{
		switch (format)
		{
			case SECONDS:
				return String.valueOf((int) Math.ceil(ticks * 0.6));
			case DECIMALS:
				return String.format("%.1fs", ticks * 0.6);
			case TICKS:
			default:
				return String.valueOf(ticks);
		}
	}
}

